// Details: Service-specific external object payload selected by `type`.
//
// Exactly one variant pointer is set when the payload matched a known
// variant. Raw always carries the undecoded payload.
type Details struct {
	R2Bucket   *R2Bucket
	D1Database *D1Database
	Raw        JSONValue
}

// UnmarshalJSON decodes the union payload.
func (u *Details) UnmarshalJSON(data []byte) error {
	if err := json.Unmarshal(data, &u.Raw); err != nil {
		return err
	}
	tag := u.Raw.Get("type").StringValue()
	switch tag {
	case "d1_database":
		var v D1Database
		if err := json.Unmarshal(data, &v); err != nil {
			return err
		}
		u.D1Database = &v
		return nil
	case "r2_bucket":
		var v R2Bucket
		if err := json.Unmarshal(data, &v); err != nil {
			return err
		}
		u.R2Bucket = &v
		return nil
	default:
		return fmt.Errorf("Details: unknown type tag %q", tag)
	}
}

// MarshalJSON re-encodes whichever variant is set.
func (u Details) MarshalJSON() ([]byte, error) {
	if u.R2Bucket != nil {
		return json.Marshal(u.R2Bucket)
	}
	if u.D1Database != nil {
		return json.Marshal(u.D1Database)
	}
	return json.Marshal(u.Raw)
}

