// SlackDeliveryOutcome: What happened to one agent message this platform sent to a Slack channel. Lets you confirm delivery, or find out why a reply never arrived, without reading the channel's mirrored conversation.
type SlackDeliveryOutcome struct {
	// Agent: ID of the agent whose message this was.
	Agent *string `json:"agent,omitempty"`
	// Binding: ID of the Slack channel binding in force for this send. `null` when no binding could be resolved, in which case the send was treated as cross-org and floored on that basis.
	Binding *string `json:"binding,omitempty"`
	// Channel: Slack channel ID the send was addressed to.
	Channel string `json:"channel"`
	// FailureReason: For a `failed` send, a short machine-readable cause `slack:<slack_error_code>` when Slack rejected the call, or `floor_config` when the content floor could not be evaluated and the send failed closed.
	FailureReason *string `json:"failure_reason,omitempty"`
	// GuardKind: For a withheld send, the kind of guard that stopped it `RegexMatch`, `ContainsAny`, `ContainsString`, or `LLMJudge`. `null` when the send was not withheld by a guard.
	GuardKind *string `json:"guard_kind,omitempty"`
	// GuardLabels: For a withheld send, the labels of the guards that stopped it (for example `Contains AWS access key ID`). These are the content policy's own descriptions, recorded as they read at the time of the send; they never contain the withheld message.
	GuardLabels []string `json:"guard_labels,omitempty"`
	// ID: Unique identifier for this delivery outcome.
	ID string `json:"id"`
	// Message: ID of the platform message this attempt was carrying. Reading that message still requires access to its thread this field correlates, it does not grant.
	Message *string `json:"message,omitempty"`
	// Operation: Which Slack call the attempt made. `post` a new message in the channel, visible to everyone in it. `post_ephemeral` a message only one named channel member could see; Slack returns no durable timestamp for one, so it has no `thread_ts` to correlate and cannot be found in the channel's history afterwards. `update` replacing an existing message (typically a thinking placeholder).
	Operation string `json:"operation"`
	// Outcome: What happened to the send. `delivered` Slack accepted the message. `floored` a deterministic content guard withheld it, so it never left. `judge_refused` the cross-org judge decided it was not appropriate for this channel's audience. `failed` Slack rejected the call, or the content floor could not be evaluated and the send failed closed.
	Outcome string `json:"outcome"`
	// RecordedAt: When the send was attempted.
	RecordedAt Time `json:"recorded_at"`
	// ThreadTs: Slack thread timestamp the send targeted, letting attempts be grouped into the conversation they belong to. `null` for a top-level channel post.
	ThreadTs *string `json:"thread_ts,omitempty"`
}

