// SolutionUpgradeResult: The outcome of a solution upgrade operation, including the computed diff and conflict status.
type SolutionUpgradeResult struct {
	// Changes: Ordered list of individual config change entries representing every add, update, noop, orphan, and delete in the diff.
	Changes []SolutionDiffEntry `json:"changes"`
	// Code: Machine-readable conflict code when `status` is `"conflict"`, e.g. `"review_required"`. `null` when there is no conflict.
	Code *string `json:"code,omitempty"`
	// DryRun: `true` when the upgrade was computed without writing any changes; `false` when changes were committed.
	DryRun bool `json:"dry_run"`
	// ExistingSolutionVersion: Version string of the currently installed solution, as declared in its manifest. `null` if no prior version is installed.
	ExistingSolutionVersion *string `json:"existing_solution_version,omitempty"`
	// IncomingSolutionVersion: Version string of the incoming solution to be installed, as declared in its manifest. `null` if the incoming manifest omits a version.
	IncomingSolutionVersion *string `json:"incoming_solution_version,omitempty"`
	// Message: Human-readable description of the conflict or error. `null` when there is no conflict.
	Message *string `json:"message,omitempty"`
	// ReviewFingerprint: Opaque fingerprint that uniquely identifies this diff. Pass this value as `review_fingerprint` on a subsequent non-dry-run upgrade call to confirm you have reviewed the diff. `null` if not applicable.
	ReviewFingerprint *string `json:"review_fingerprint,omitempty"`
	// Status: Overall result of the upgrade. `"ready"` means the upgrade can proceed; `"conflict"` means a blocking issue was detected and the upgrade was not applied.
	Status string `json:"status"`
	// Summary: Aggregate counts of each action type across all diff entries.
	Summary *SolutionDiffSummary `json:"summary"`
	// VersionChange: Describes the nature of the version transition. One of `"upgrade"`, `"downgrade"`, `"same"`, or `"unknown"`.
	VersionChange string `json:"version_change"`
}

// SolutionUpgradeResponse: Response returned by the solution upgrade endpoint, containing the solution record, the full upgrade diff, and the resulting installed configs.
type SolutionUpgradeResponse struct {
	// CreatedAt: When the solution config record was first created (ISO 8601). `null` if unavailable.
	CreatedAt *Time `json:"created_at,omitempty"`
	// ID: Config ID of the solution record (`cfg_...`).
	ID string `json:"id"`
	// InstalledConfigs: List of config entries that were installed or updated as part of this upgrade. Empty when `dry_run` is `true` or when no configs changed.
	InstalledConfigs []InstalledConfigEntry `json:"installed_configs,omitempty"`
	// Kind: Object type discriminator. Always `"Solution"`.
	Kind string `json:"kind"`
	// LookupKey: Human-readable stable identifier for this solution config. `null` if not assigned.
	LookupKey *string `json:"lookup_key,omitempty"`
	// Solution: Summary of the solution being upgraded, including its name, manifest metadata, and tag keys.
	Solution *SolutionSummary `json:"solution"`
	// UpdatedAt: When the solution config record was last modified (ISO 8601). `null` if unavailable.
	UpdatedAt *Time `json:"updated_at,omitempty"`
	// UpgradeResult: Detailed result of the upgrade operation, including the computed diff and any conflict information.
	UpgradeResult *SolutionUpgradeResult `json:"upgrade_result"`
	// VirtualPath: Hierarchical path of the solution in the config tree. `null` if not assigned.
	VirtualPath *string `json:"virtual_path,omitempty"`
}
